<?php

namespace Database\Seeders;

use App\Models\Role;
use App\Models\SidebarMenu;
use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

/**
 * Turns the hand-written sidebar into rows.
 *
 * The structure is read from a map generated by parsing
 * resources/views/sections/menu-legacy.blade.php, so the groups, the order, the
 * routes, the icons and — most importantly — the permission each entry sits
 * behind all come from the file that is actually in use, not from a transcript
 * of it.
 *
 * Every role is granted every menu to begin with. That is deliberate: today
 * there is no such thing as a role-menu grant, and visibility is decided purely
 * by permissions. Granting everything makes `role_menus` a no-op on day one, so
 * the sidebar after seeding is identical to the sidebar before it. An
 * administrator then revokes from Settings > Assign Menus as they wish.
 *
 * Re-runnable: matching rows are updated rather than duplicated.
 */
class SidebarMenuSeeder extends Seeder
{

    /** Entries the hand-written sidebar renders twice, once per branch of an if/else. */
    protected array $seen = [];

    /**
     * Entries whose condition cannot be reduced to one permission, role or
     * module, written out by hand after reading each one.
     *
     * Everything here was found by the verification diff, not guessed: each is
     * an entry the generated map would have shown to somebody who could not see
     * it before. Keyed by route name.
     */
    protected array $overrides = [
        // "(admin || client) && $gdpr->enable_gdpr == 1". GDPR is switched off
        // in settings, so nobody saw this. Seeded switched off rather than
        // pretending the role test alone is the gate; turn it on in Menu
        // Management if GDPR is ever enabled.
        'gdpr.index' => ['is_active' => 0, 'role_rule' => 'not_employee'],

        // Both are additionally gated on the PayFast gateway being active,
        // which it is not. Same reasoning as GDPR.
        'subscriptions.index' => ['is_active' => 0, 'role_rule' => 'not_client', 'permission_key' => 'view_invoices', 'permission_rule' => 'any', 'module' => 'invoices'],
        'client.subscriptions.index' => ['is_active' => 0, 'role_rule' => 'client_only', 'permission_key' => 'view_invoices', 'permission_rule' => 'any', 'module' => 'invoices'],

        // Sits inside "admin || any of six dashboard permissions == 4". The
        // role half is redundant — an administrator holds all six — so the
        // permission half alone reproduces it. A comma-separated key means
        // "any of these".
        'dashboard.advanced' => [
            'permission_key' => 'view_overview_dashboard,view_project_dashboard,view_client_dashboard,view_hr_dashboard,view_ticket_dashboard,view_finance_dashboard',
            'permission_rule' => 'all',
        ],

        // The only entry gated through user()->permission() rather than the
        // $sidebarUserPermissions array, which returns 'all'/'none' instead of
        // a number.
        'leave-year-end.index' => ['permission_key' => 'manage_leave_setting', 'permission_rule' => 'setting_all'],

        // "view_appreciation == 5 && manage_award == 4" — the Awards entry is
        // what somebody sees *instead of* Appreciations when they may only see
        // their own. view_appreciation is the half that decides: an
        // administrator holds 4, so they get Appreciations and not this.
        // Both halves are stored, paired by position, so a person with
        // view_appreciation == 5 but manage_award != 4 still sees nothing.
        'awards.index' => ['permission_key' => 'view_appreciation,manage_award', 'permission_rule' => 'own,all'],

        // The plain Messages menu is the non-client branch of an if/else; the
        // client branch depends on two message settings that are both off.
        'messages.index' => ['role_rule' => 'not_client', 'module' => 'messages'],

        // Payroll was written against the administrator role, so the generated
        // map carried role_rule 'admin' and payroll could not be given to
        // anybody without making them an administrator of everything. It has a
        // permission of its own now; the role test goes.
        'payroll-run.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
        'payroll-dashboard.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
        'payslips.generated' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
        'payroll-register.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
        'pay-elements.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],

        // Everybody's own payslips, scoped to whoever is signed in by the
        // controller. There is nothing to gate it on and nothing to gate it
        // from: it only ever shows the reader their own.
        'my-payslips.index' => ['permission_key' => null, 'permission_rule' => null, 'role_rule' => 'not_client'],

        // The legacy Payslips screen embeds the whole-company calculator and is
        // where a single payslip is generated. LegacyController sends anybody
        // who cannot run payroll to their own payslips instead, so for them the
        // entry was a second link to My Payslips under a different name — it is
        // shown to whoever actually gets the calculator. Offer Letter is the
        // employee picker that leads into it, so it goes with it.
        'payslips.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
        'payslip-entry.index' => ['permission_key' => 'manage_payroll', 'permission_rule' => 'setting_all', 'role_rule' => null],
    ];

    /**
     * The biometric screens show the whole device register, never just the
     * person signed in: the punch log, the mapping list, the comparison, the
     * employee dropdown on the profile. The sidebar was generated with the
     * permission rule the Blade file carried, "any", which let anybody holding
     * view_attendance for their own record see the links — and the controller
     * let them through as well.
     *
     * Both halves now ask for the permission to see everybody's attendance.
     * BiometricController's constructor is the gate; this is the sidebar
     * agreeing with it, so nobody is shown a link that refuses them.
     */
    /**
     * The order the entries of a section are listed in.
     *
     * The generated order follows the hand-written sidebar, which grew by
     * addition rather than by design: HR opened with Employees and then jumped
     * straight to Exit and Termination before Probation, put the org structure
     * last, and listed payroll in the middle of the leave screens. Biometric
     * was in the order the screens were built, not the order they are used.
     *
     * These two read as the work actually runs — set up, then use, then review,
     * then finish — and group by kind within that. Keyed by the section's slug,
     * then the route of each entry in the order it should appear. Anything not
     * named keeps its place after the ones that are.
     */
    protected array $flowOrder = [
        'hr' => [
            // the organisation itself
            'departments.index', 'designations.index',
            // the people in it, from joining
            'employees.index', 'payslip-entry.index', 'identity.index', 'probation-requests.index',
            // their time
            'attendances.index', 'shifts.index', 'holidays.index',
            // recognition
            'appreciations.index', 'awards.index',
            // and leaving
            'resignations.index', 'resignation-management.index',
            'employee-exit.index', 'employee-termination.index',
        ],
        'leave-management' => [
            'leaves.index', 'leave-management.index', 'leave-year-end.index',
        ],
        'payroll' => [
            // their own first, then the whole company's, then what leaving costs
            'my-payslips.index', 'payslips.index',
            'pay-elements.index', 'payroll-run.index', 'payslips.generated',
            'payroll-register.index', 'payroll-dashboard.index',
            'income-tax.index', 'statutory-returns.index', 'settlements.index',
        ],
        'biometric' => [
            // set the devices up and say who is who
            'biometric.devices', 'biometric.employees', 'biometric.comparison',
            // pull what they recorded
            'biometric.calendar', 'biometric.punch-log', 'biometric.attendance',
            // read it before trusting it
            'biometric.shifts', 'biometric.exceptions', 'biometric.profile',
            // then put it into the ERP, and check what went
            'biometric.attendance-sync', 'biometric.sync-logs', 'biometric.actions',
        ],
    ];

    protected array $deviceWideRoutes = [
        'biometric.calendar', 'biometric.attendance', 'biometric.attendance-sync',
        'biometric.punch-log', 'biometric.profile', 'biometric.exceptions',
        'biometric.shifts', 'biometric.employees', 'biometric.comparison',
        'biometric.devices', 'biometric.sync-logs', 'biometric.actions',
    ];

    public function run(): void
    {
        $map = $this->structure();

        if ($map === []) {
            $this->command?->error('No sidebar map found. Run the parser first.');

            return;
        }

        $companyId = DB::table('companies')->orderBy('id')->value('id');
        $order = 0;

        DB::transaction(function () use ($map, $companyId, &$order) {
            foreach ($map as $group) {
                $label = $this->label($group['label']);

                if ($label === null || $this->alreadySeen('group:' . $label)) {
                    continue;
                }

                // Settings is a special case: the hand-written sidebar sent an
                // administrator to company-settings and everybody else to their
                // own profile settings. database-menu-item reproduces that, but
                // only when the row carries no route of its own.
                $isSettings = $group['route'] === 'company-settings.index';

                $parent = $this->write([
                    'company_id' => $companyId,
                    'parent_id' => null,
                    'name' => $label,
                    'slug' => $isSettings ? 'settings' : $this->slug($group['route'], $label),
                    'route' => $isSettings ? null : $group['route'],
                    'icon' => $group['icon'],
                    'level' => 0,
                    'sort_order' => ++$order,
                    'permission_key' => $group['condition']['permission_key'] ?? null,
                    'permission_rule' => $group['condition']['permission_rule'] ?? null,
                    'role_rule' => $group['condition']['role_rule'] ?? null,
                    'module' => $group['condition']['module'] ?? null,
                ]);

                $childOrder = 0;

                foreach ($group['items'] as $item) {
                    $itemLabel = $this->label($item['label']);

                    if ($itemLabel === null || $item['route'] === null) {
                        continue;
                    }

                    if ($this->alreadySeen('item:' . $parent->id . ':' . $item['route'])) {
                        continue;
                    }

                    $this->write([
                        'company_id' => $companyId,
                        'parent_id' => $parent->id,
                        'name' => $itemLabel,
                        'slug' => $this->slug($item['route'], $itemLabel),
                        'route' => $item['route'],
                        'icon' => null,
                        'level' => 1,
                        'sort_order' => ++$childOrder,
                        'permission_key' => $item['condition']['permission_key'] ?? null,
                        'permission_rule' => $item['condition']['permission_rule'] ?? null,
                        'role_rule' => $item['condition']['role_rule'] ?? null,
                        'module' => $item['condition']['module'] ?? null,
                    ]);
                }
            }
        });

        $this->seedSettingsChildren($companyId);

        $this->applyFlowOrder($companyId);

        $this->grantEverythingToEveryRole();

        User::forgetAllMenuCaches();

        $this->command?->info(sprintf(
            'Seeded %d menus (%d top level) and %d role grants.',
            SidebarMenu::count(),
            SidebarMenu::whereNull('parent_id')->count(),
            DB::table('role_menus')->count()
        ));
    }

    /**
     * The Settings page has its own menu of 38 entries, which the main sidebar
     * never listed. They are seeded as children of the Settings group so that
     * Menu Management can show them and Assign Menus can grant or revoke them
     * per role.
     *
     * The settings menu itself stays hand-written, so every one of its existing
     * permission checks still runs. The grant is an extra filter applied in
     * SettingMenuItem::shouldRender() — it can hide an entry, never reveal one.
     *
     * No permission_key is stored: the Blade @if around each entry already does
     * that job, and duplicating it here would mean two places to keep in step.
     */
    protected function seedSettingsChildren(?int $companyId): void
    {
        $path = database_path('seeders/data/settings_structure.json');

        if (!is_file($path)) {
            return;
        }

        $items = json_decode(file_get_contents($path), true) ?: [];
        $settings = SidebarMenu::where('company_id', $companyId)->where('slug', 'settings')->first();

        if (!$settings || $items === []) {
            return;
        }

        $order = 0;

        foreach ($items as $item) {
            $this->write([
                'company_id' => $companyId,
                'parent_id' => $settings->id,
                'name' => $item['label'],
                'slug' => $this->slug($item['route'], $item['label']),
                'route' => $item['route'],
                'icon' => null,
                'level' => 1,
                'sort_order' => ++$order,
                'permission_key' => null,
                'permission_rule' => null,
                'role_rule' => null,
                'module' => null,
            ]);
        }
    }

    /**
     * Put the sections named in $flowOrder into that order.
     *
     * Runs after everything is seeded, so it reorders whatever is there rather
     * than depending on the order the entries were written in. An entry the
     * list does not name keeps its relative place, after the ones it does.
     */
    protected function applyFlowOrder(int $companyId): void
    {
        foreach ($this->flowOrder as $slug => $routes) {
            $parent = SidebarMenu::where('company_id', $companyId)->where('slug', $slug)->first();

            if (!$parent) {
                continue;
            }

            $wanted = array_flip($routes);
            $children = SidebarMenu::where('parent_id', $parent->id)->orderBy('sort_order')->get();

            // Named first, in the order given; then the rest as they were.
            $ordered = $children
                ->sortBy(fn ($child, $i) => [$wanted[$child->route] ?? count($routes), $i])
                ->values();

            foreach ($ordered as $position => $child) {
                $child->sort_order = $position + 1;
                $child->saveQuietly();
            }
        }
    }

    /**
     * Insert or update one row, matched on its slug within the company.
     */
    protected function write(array $attributes): SidebarMenu
    {
        // A hand-written override wins over whatever the parser worked out.
        $route = $attributes['route'] ?? null;

        if ($route !== null && isset($this->overrides[$route])) {
            $attributes = array_merge($attributes, $this->overrides[$route]);
        }

        if ($route !== null && in_array($route, $this->deviceWideRoutes, true)) {
            $attributes['permission_rule'] = 'all';
        }

        $menu = SidebarMenu::where('company_id', $attributes['company_id'])
            ->where('slug', $attributes['slug'])
            ->first();

        if ($menu) {
            // is_active is left alone on update: an administrator may have
            // switched an entry on or off, and re-running the seeder must not
            // undo that. It only applies on first insert.
            unset($attributes['is_active']);
            $menu->fill($attributes)->save();

            return $menu;
        }

        return SidebarMenu::create($attributes + ['is_active' => 1]);
    }

    /**
     * Every role gets every menu, so that seeding changes nothing on its own.
     */
    protected function grantEverythingToEveryRole(): void
    {
        $menuIds = SidebarMenu::pluck('id');
        $now = now();
        $rows = [];

        // A role that has been given a deliberate set through Assign Menus is
        // left alone. Granting it the whole tree again would silently undo
        // that work every time this seeder runs — which it did, wiping the
        // Admin role back to all 115 menus.
        //
        // Two roles are not left alone. One that holds nothing yet is new and
        // takes everything. And the administrator role always holds every
        // menu — AssignMenuController enforces that too — so a menu added by a
        // later seed reaches it rather than reaching nobody at all.
        $held = DB::table('role_menus')->selectRaw('role_id, COUNT(*) AS n')
            ->groupBy('role_id')->pluck('n', 'role_id');

        foreach (Role::withoutGlobalScopes()->get() as $role) {
            $isNew = ($held[$role->id] ?? 0) === 0;

            if (!$isNew && $role->name !== 'admin') {
                continue;
            }

            foreach ($menuIds as $menuId) {
                $rows[] = [
                    'role_id' => $role->id,
                    'menu_id' => $menuId,
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            }
        }

        foreach (array_chunk($rows, 500) as $chunk) {
            // Re-running must not fail on the (role_id, menu_id) unique key.
            DB::table('role_menus')->insertOrIgnore($chunk);
        }
    }

    /**
     * A translation key becomes its text; anything else is already text.
     */
    protected function label(?string $label): ?string
    {
        if ($label === null || trim($label) === '') {
            return null;
        }

        if (!str_contains($label, '.')) {
            return html_entity_decode($label, ENT_QUOTES | ENT_HTML5);
        }

        $translated = __($label);

        // __() hands back the key itself when there is no translation.
        return html_entity_decode($translated === $label ? Str::headline(Str::afterLast($label, '.')) : $translated,
            ENT_QUOTES | ENT_HTML5);
    }

    protected function slug(?string $route, string $label): string
    {
        $base = $route ? Str::slug(str_replace('.', '-', $route)) : Str::slug($label);
        $slug = $base;
        $i = 1;

        while (in_array($slug, $this->seen['slugs'] ?? [], true)) {
            $slug = $base . '-' . $i++;
        }

        $this->seen['slugs'][] = $slug;

        return $slug;
    }

    protected function alreadySeen(string $key): bool
    {
        if (isset($this->seen[$key])) {
            return true;
        }

        $this->seen[$key] = true;

        return false;
    }

    /**
     * The parsed sidebar map, shipped beside this seeder.
     */
    protected function structure(): array
    {
        $path = database_path('seeders/data/sidebar_structure.json');

        if (!is_file($path)) {
            return [];
        }

        return json_decode(file_get_contents($path), true) ?: [];
    }

}
